/** Headless match for V10 renderer.isWater(x,z): downward ray from Y=30.
 * The caller separately enforces the original road-distance / altitude gates,
 * check cadence, recovery penalties, and checkpoint-preserving recovery.
 * Input is generated by tools/export_water.py, never accepted from clients.
 */
export function createWaterQuery(data) {
  if (data?.schemaVersion !== 1 || !Array.isArray(data.triangles) || !Number.isFinite(data.rayOriginY)) {
    throw new TypeError('Invalid authored water data');
  }
  const originY = data.rayOriginY;
  const triangles = data.triangles.map((t) => {
    if (!Array.isArray(t) || t.length !== 9 || !t.every(Number.isFinite)) throw new TypeError('Invalid water triangle');
    const [ax, ay, az, bx, by, bz, cx, cy, cz] = t;
    const determinant = (bz-cz)*(ax-cx)+(cx-bx)*(az-cz);
    return { ax, ay, az, bx, by, bz, cx, cy, cz, determinant,
      minX: Math.min(ax,bx,cx), maxX: Math.max(ax,bx,cx), minZ: Math.min(az,bz,cz), maxZ: Math.max(az,bz,cz) };
  });
  return function isWater(x, z) {
    if (!Number.isFinite(x) || !Number.isFinite(z)) return false;
    for (const t of triangles) {
      if (x<t.minX || x>t.maxX || z<t.minZ || z>t.maxZ || Math.abs(t.determinant)<1e-12) continue;
      const a=((t.bz-t.cz)*(x-t.cx)+(t.cx-t.bx)*(z-t.cz))/t.determinant;
      const b=((t.cz-t.az)*(x-t.cx)+(t.ax-t.cx)*(z-t.cz))/t.determinant;
      const c=1-a-b;
      if (a < -1e-10 || b < -1e-10 || c < -1e-10) continue;
      if (a*t.ay+b*t.by+c*t.cy <= originY+1e-10) return true;
    }
    return false;
  };
}
